-- Anexo A - banco de dados do servidor, adaptado para SQLite.
-- Diferencas em relacao ao script original (PostgreSQL):
--   * "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY" virou
--     "INTEGER PRIMARY KEY AUTOINCREMENT" (e assim que o SQLite gera ids);
--   * "IF NOT EXISTS" em cada tabela, porque o script roda a cada inicializacao.
-- As chaves estrangeiras (e o ON DELETE CASCADE) dependem de foreign_keys=on,
-- ligado na URL de conexao em application.yml.

CREATE TABLE IF NOT EXISTS usuario (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome VARCHAR(100) NOT NULL,
  email VARCHAR(150) NOT NULL UNIQUE,
  senha VARCHAR(255) NOT NULL,
  perfil VARCHAR(10) NOT NULL DEFAULT 'CLIENTE'
    CHECK (perfil IN ('CLIENTE', 'ADMIN')),
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS categoria (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome VARCHAR(60) NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS produto (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  categoria_id BIGINT NOT NULL REFERENCES categoria (id),
  nome VARCHAR(100) NOT NULL,
  descricao VARCHAR(500),
  preco NUMERIC(10,2) NOT NULL CHECK (preco > 0),
  imagem_url VARCHAR(255),
  tempo_preparo_min INTEGER
);

CREATE TABLE IF NOT EXISTS adicional (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  produto_id BIGINT NOT NULL REFERENCES produto (id) ON DELETE CASCADE,
  nome VARCHAR(80) NOT NULL,
  preco NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (preco >= 0)
);

CREATE TABLE IF NOT EXISTS carrinho (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  usuario_id BIGINT NOT NULL UNIQUE REFERENCES usuario (id),
  atualizado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS item_carrinho (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  carrinho_id BIGINT NOT NULL REFERENCES carrinho (id) ON DELETE CASCADE,
  produto_id BIGINT NOT NULL REFERENCES produto (id),
  quantidade INTEGER NOT NULL CHECK (quantidade > 0),
  observacao VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS item_carrinho_adicional (
  item_carrinho_id BIGINT NOT NULL
    REFERENCES item_carrinho (id) ON DELETE CASCADE,
  adicional_id BIGINT NOT NULL REFERENCES adicional (id),
  PRIMARY KEY (item_carrinho_id, adicional_id)
);

CREATE TABLE IF NOT EXISTS pedido (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo VARCHAR(20) NOT NULL UNIQUE,
  usuario_id BIGINT NOT NULL REFERENCES usuario (id),
  status VARCHAR(20) NOT NULL DEFAULT 'RECEBIDO'
    CHECK (status IN ('RECEBIDO', 'EM_PREPARO',
                      'SAIU_PARA_ENTREGA', 'ENTREGUE')),
  forma_pagamento VARCHAR(10) NOT NULL
    CHECK (forma_pagamento IN ('PIX', 'CARTAO', 'DINHEIRO')),
  cep CHAR(8) NOT NULL,
  logradouro VARCHAR(150) NOT NULL,
  numero VARCHAR(10) NOT NULL,
  bairro VARCHAR(80) NOT NULL,
  cidade VARCHAR(80) NOT NULL,
  subtotal NUMERIC(10,2) NOT NULL,
  taxa_entrega NUMERIC(10,2) NOT NULL DEFAULT 0,
  total NUMERIC(10,2) NOT NULL,
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS item_pedido (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  pedido_id BIGINT NOT NULL REFERENCES pedido (id) ON DELETE CASCADE,
  produto_id BIGINT NOT NULL REFERENCES produto (id),
  quantidade INTEGER NOT NULL CHECK (quantidade > 0),
  preco_unitario NUMERIC(10,2) NOT NULL,
  observacao VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS item_pedido_adicional (
  item_pedido_id BIGINT NOT NULL
    REFERENCES item_pedido (id) ON DELETE CASCADE,
  adicional_id BIGINT NOT NULL REFERENCES adicional (id),
  preco NUMERIC(10,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (item_pedido_id, adicional_id)
);
